import json
d=json.load(open("probe.json")); J=lambda k: json.loads(d[k]["body"])
u=J("UniProt"); print("UniProt:", u["primaryAccession"], u["uniProtkbId"], "len", u["sequence"]["length"], "| entryVersion", u["entryAudit"]["entryVersion"], "| lastAnnot", u["entryAudit"]["lastAnnotationUpdateDate"], "| release hdr", {k:v for k,v in d["UniProt"]["headers"].items() if "release" in k.lower()})
print("  xref DBs:", len(u.get("uniProtKBCrossReferences",[])), "e.g. PDB entries:", sum(1 for x in u["uniProtKBCrossReferences"] if x["database"]=="PDB"))
e=J("Ensembl"); print("Ensembl:", e["id"], e["seq_region_name"], e["start"], e["end"], e["strand"], e.get("assembly_name"), e.get("biotype"))
g=J("NCBI Gene")["result"]["6647"]; print("NCBI Gene:", g["name"], g["description"], "| chr", g["chromosome"], g["maplocation"], "| summary chars", len(g.get("summary","")))
c=J("ClinVar")["esearchresult"]; print("ClinVar records:", c["count"])
p=J("RCSB PDB"); print("PDB entries:", p["total_count"])
a=J("AlphaFold DB")[0]; print("AlphaFold:", a.get("entryId"), "version", a.get("latestVersion"), "| pLDDT", a.get("globalMetricValue"), "| created", a.get("modelCreatedDate"), "| keys", [k for k in a if 'Url' in k][:4])
i=J("InterPro"); print("InterPro entries:", i["count"], [r["metadata"]["accession"]+" "+r["metadata"]["name"] for r in i["results"]][:6])
q=J("QuickGO"); print("QuickGO annotations:", q["numberOfHits"])
s=J("STRING"); print("STRING partners:", [(x["preferredName_B"], x["score"]) for x in s])
r=J("Reactome"); print("Reactome pathways:", len(r), [x["displayName"] for x in r][:6])
k=d["KEGG"]["body"].strip().splitlines(); print("KEGG pathways:", len(k), k[:5])
gd=J("GEO")["esearchresult"]; print("GEO DataSets/Series hits:", gd["count"])
pr=J("PRIDE"); print("PRIDE projects:", len(pr) if isinstance(pr,list) else type(pr), (pr[0].get("accession") if isinstance(pr,list) and pr else ""))
